const lineas = $('Extract from File').all().map(i => i.json);
const matches = $input.first().json.output.matches;

const dudosos = matches.filter(m => m.status !== 'MATCH' || m.confianza < 0.85);

return dudosos.map(m => {
  const pedidos = [...new Set(
    lineas.filter(l => l.producto_reportado === m.producto_reportado).map(l => l.pedido_id)
  )].join(', ');

  const noExiste = m.status === 'NO_ENCONTRADO';
  const propuesta = noExiste
    ? 'Confirmar que no existe y dejar el pedido en revisión manual'
    : (m.propuesta || (m.candidatos && m.candidatos[0]) || m.producto_catalogo);

  const siApruebas = noExiste
    ? 'queda como NO_ENCONTRADO (confirmado).'
    : `se calcula con: ${propuesta}.`;

  const pregunta_html = `⚠️ *PRODUCTO DUDOSO*\n\n` +
    `📦 *Producto del CSV:* ${m.producto_reportado}\n` +
    `🛒 *Pedido(s):* ${pedidos}\n` +
    `❓ *Problema:* ${m.motivo}\n` +
    `💡 *Propuesta:* ${propuesta}\n\n` +
    `✅ *Si apruebas:* ${siApruebas}\n` +
    `❌ *Si rechazas:* queda en REVISIÓN MANUAL.`;

  return { json: { ...m, pedidos, propuesta, pregunta_html } };
});

