parameters.jsCode:
const CATALOGO = {
  'Whey Protein Concentrado Chocolate 908 g': 145000,
  'Whey Protein Concentrado Vainilla 908 g': 145000,
  'Whey Protein Isolate Fresa 1.13 kg': 200000,
  'Whey Protein Isolate Fresa 2.27 kg': 310000,
  'Creatina Monohidratada Neutro 300 g': 75000,
  'Pre-Entreno Explosive Sandía 300 g': 110000,
  'BCAA 2:1:1 Mango 400 g': 85000,
  'Glutamina Neutro 300 g': 80000,
  'Multivitamínico Hombre x60 cápsulas': 58000,
  'Multivitamínico Mujer x60 cápsulas': 58000,
  'Colágeno Hidrolizado Limón 300 g': 92000,
  'Omega 3 1000 mg x120 cápsulas': 70000,
  'Quemador Termogénico Black x90 cápsulas': 98000,
  'Barra Proteica Caja x12 Choco Chip': 65000
};

// Normaliza texto: minúsculas y sin tildes
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const TARIFAS = { 'estandar': 11000, 'dia siguiente': 15000, 'mismo dia': 16000 };
const CIUDADES_PRINCIPALES = ['bogota', 'cali', 'medellin'];

// 1. Datos base
const lineas = $('Extract from File').all().map(i => i.json);
const matches = $('AI Agent').first().json.output.matches;
const dudosos = $('Separar casos dudosos').all().map(i => i.json);
const respuestas = $input.all().map(i => i.json);

// 2. Estado de cada producto
const estado = {};
for (const m of matches) {
  estado[m.producto_reportado] = {
    status: m.status,
    producto: m.producto_catalogo,
    precio: CATALOGO[m.producto_catalogo] ?? null
  };
}

// 3. Procesar decisiones del humano (Chat / Aprobaciones)
dudosos.forEach((d, idx) => {
  const r = respuestas[idx] || {};

  // Lógica robusta para detectar si el humano aprobó
  const decisionTexto = norm(r.response || r.decision || r['Decisión'] || '');
  const aprobado = 
    r?.data?.approved === true || 
    r?.approved === true || 
    decisionTexto.includes('approve') || 
    decisionTexto.includes('aprobar') ||
    decisionTexto.includes('true');

  if (!aprobado) {
    estado[d.producto_reportado] = { status: 'REVISIÓN MANUAL', producto: '', precio: null };
  } else if (d.status === 'NO_ENCONTRADO') {
    estado[d.producto_reportado] = { status: 'NO_ENCONTRADO', producto: '', precio: null };
  } else {
    estado[d.producto_reportado] = {
      status: 'MATCH (aprobado)',
      producto: d.propuesta,
      precio: CATALOGO[d.propuesta] ?? null
    };
  }
});

// 4. Agrupar por pedido
const pedidos = {};
for (const l of lineas) {
  const e = estado[l.producto_reportado] || { precio: null };
  const cantidad = Number(l.cantidad) || 1;

  if (!pedidos[l.pedido_id]) {
    pedidos[l.pedido_id] = {
      pedido_id: l.pedido_id,
      cliente: l.cliente,
      es_miembro: norm(l.es_miembro) === 'si',
      ciudad: norm(l.ciudad_destino),
      metodo: norm(l.metodo_envio),
      subtotal: 0,
      lineasSinPrecio: 0,
      cobrado: parseFloat(l.valor_cobrado_actual) || 0
    };
  }

  if (e.precio == null) {
    pedidos[l.pedido_id].lineasSinPrecio += 1;
  } else {
    pedidos[l.pedido_id].subtotal += e.precio * cantidad;
  }
}

// 5. Aplicar reglas de negocio y armar el resultado final
return Object.values(pedidos).map(p => {
  // Si faltan precios por aprobar o rechazaste
  if (p.lineasSinPrecio > 0) {
    return { 
      json: {
        pedido_id: p.pedido_id, 
        cliente: p.cliente, 
        subtotal: p.subtotal,
        costo_envio: 'N/A', 
        total_correcto: 'N/A', 
        cobrado: p.cobrado, 
        diferencia: 'N/A',
        estado_final: '⚠️ REVISIÓN MANUAL (producto sin precio validado)'
      }
    };
  }

  // Calcular costo de envío
  let costoEnvio;
  if (p.es_miembro && p.subtotal > 200000) {
    costoEnvio = 0;
  } else if (CIUDADES_PRINCIPALES.includes(p.ciudad)) {
    costoEnvio = TARIFAS[p.metodo];
  } else {
    costoEnvio = 15000;
  }

  // Validar que el método de envío exista
  if (costoEnvio === undefined) {
    return { 
      json: {
        pedido_id: p.pedido_id, 
        cliente: p.cliente, 
        subtotal: p.subtotal,
        costo_envio: 'N/A', 
        total_correcto: 'N/A', 
        cobrado: p.cobrado, 
        diferencia: 'N/A', 
        estado_final: '⚠️ REVISIÓN MANUAL (método de envío no reconocido)'
      }
    };
  }

  // Calcular total y diferencia
  const total = p.subtotal + costoEnvio + 10000; // Recargo fijo
  const diferencia = p.cobrado - total; // + = cobrado de más | - = cobrado de menos

  return { 
    json: {
      pedido_id: p.pedido_id, 
      cliente: p.cliente, 
      subtotal: p.subtotal,
      costo_envio: costoEnvio, 
      total_correcto: total, 
      cobrado: p.cobrado, 
      diferencia,
      estado_final: diferencia === 0 ? '✅ OK' : '❌ CORREGIR'
    }
  };
});
